  99:     private static string QuoteWindowsArgument(string argument)
 100:     {
 101:         if (argument.Length > 0 &&
 102:             !argument.Any(character =>
 103:                 char.IsWhiteSpace(character) || character == '"'))
 104:         {
 105:             return argument;
 106:         }
 107: 
 108:         var quoted = new StringBuilder(argument.Length + 2);
 109:         quoted.Append('"');
 110:         var backslashes = 0;
 111:         foreach (var character in argument)
 112:         {
 113:             if (character == '\\')
 114:             {
 115:                 backslashes++;
 116:                 continue;
 117:             }
 118: 
 119:             if (character == '"')
 120:             {
 121:                 quoted.Append('\\', (backslashes * 2) + 1);
 122:                 quoted.Append('"');
 123:                 backslashes = 0;
 124:                 continue;
 125:             }
 126: 
 127:             quoted.Append('\\', backslashes);
 128:             backslashes = 0;
 129:             quoted.Append(character);
 130:         }
 131: 
 132:         quoted.Append('\\', backslashes * 2);
 133:         quoted.Append('"');
 134:         return quoted.ToString();
 135:     }
