 293:     private static string QuoteWindowsArgument(string argument)
 294:     {
 295:         if (argument.Length > 0 &&
 296:             argument.All(character => !char.IsWhiteSpace(character) && character != '"'))
 297:         {
 298:             return argument;
 299:         }
 300: 
 301:         var quoted = new StringBuilder(argument.Length + 2);
 302:         quoted.Append('"');
 303:         var backslashes = 0;
 304:         foreach (var character in argument)
 305:         {
 306:             if (character == '\\')
 307:             {
 308:                 backslashes++;
 309:                 continue;
 310:             }
 311: 
 312:             if (character == '"')
 313:             {
 314:                 quoted.Append('\\', backslashes * 2 + 1);
 315:                 quoted.Append('"');
 316:                 backslashes = 0;
 317:                 continue;
 318:             }
 319: 
 320:             quoted.Append('\\', backslashes);
 321:             quoted.Append(character);
 322:             backslashes = 0;
 323:         }
 324: 
 325:         quoted.Append('\\', backslashes * 2);
 326:         quoted.Append('"');
 327:         return quoted.ToString();
 328:     }
